            total_credits_in_course = 0
            for course in self.students[student]['courses']:
                total_credits += self.students[student]['courses'][course]['credits']
                total_credits_in_course += self.students[student]['courses'][course]['credits'] * self.students[student]['courses'][course]['credit']
