        """
        Gets the cookies from the specified response,and save it to cookies_file.
        :param reponse: The response to get cookies from, dict.
        >>> cookies_util = CookiesUtil('cookies.json')
        >>> cookies_util.get_cookies({'cookies': {'key1': 'value1', 'key2': 'value2'}})
        >>> cookies_util.cookies
        {'key1': 'value1', 'key2': 'value2'}

        """
        if self.cookies is None:
            self.cookies = {}
            if reponse is not None:
                if 'cookies' in reponse:
                    self.cookies = reponse['cookies']
                else:
                    self.cookies = {}
        else:
            if reponse is not None:
                if 'cookies' in reponse:
                    self.cookies.update(reponse['cookies'])
                else:
                    self.cookies.update({})
        with open(self.cookies_file, 'w') as f:
            json.dump(self.cookies, f)

    def get_cookie(self, name):
        """
        Gets the value of the specified cookie.
        :param name: The name of the cookie to get, str.
        :return: The value of the cookie, str.
        >>> cookies_util = CookiesUtil('cookies.json')
        >>> cookies_util.get_cookie('key1')
        'value1'
        >>> cookies_util.get_cookie('key2')
        'value2'
        >>> cookies_util.get_cookie('key3')
        >>> 'value3'
        """
