            return self.cookies.get(name)
        else:
            return None

    def set_cookie(self, name, value, domain=None, path=None, expires=None, http_only=None, secure=None):
        """
        Sets the specified cookie.
        :param name: The name of the cookie to set, str.
        :param value: The value of the cookie to set, str.
        :param domain: The domain of the cookie to set, str.
        :param path: The path of the cookie to set, str.
        :param expires: The expiration date of the cookie to set, str.
