        """
        Calculate the tan value of the x-degree angle
        :param x:float
        :return:float
        >>> tricalculator = TriCalculator()
        >>> tricalculator.tan(60)
        0.5
        """
        return 1.0 - (1.0 - cos(pi * x / 180.0)) ** 2


