import zipfile
class ZipFileProcessor:  
    """
    This is a compressed file processing class that provides the ability to read and decompress compressed files
    """

    def __init__(self, file_name):
        """
        Initialize file name
        :param file_name:string
        """
        self.file_name = file_name



    def read_zip_file(self):
        """
        Get open file object
        :return:If successful, returns the open file object; otherwise, returns None
        >>> zfp = ZipFileProcessor("aaa.zip")
        >>> file = zfp.read_zip_file()
        """
        try:
            with zipfile.ZipFile(self.file_name, 'r') as zfp:
                return zfp.open(zfp.namelist()[0])
        except:
            return None

    def read_zip_file_content(self):
        """
        Get file content
        :return:If successful, returns the file content; otherwise, returns None
        >>> zfp = ZipFileProcessor("aaa.zip")
        >>> file = zfp.read_zip_file_content()
        """
        try:
            with zipfile.ZipFile(self.file_name, 'r') as zfp:
                return zfp.read(zfp.namelist()[0])
        except:
            return None

    def decompress_zip_file(self):
        """
        Decompress file
        :return:If successful, returns the decompressed file; otherwise, returns None
        >>> zfp = ZipFileProcessor("aaa.zip")
        >>> file = zfp.decompress_zip_file()
        """
        try:
            with zipfile.ZipFile(self.file_name, 'r') as zfp:
                return zfp.extract(zfp.namelist()[0])
        except:
            return None

    def decompress_zip_file_content(self):
        """
        Decompress file content
        :return:If successful, returns the decompressed file content; otherwise, returns None
        >>> zfp = ZipFileProcessor("aaa.zip")
        >>> file = zfp.decompress_zip_file_content()
        """
        try:
            with zipfile.ZipFile(self.file_name, 'r') as zfp:
                return zfp.read(zfp.namelist()[0])
        except:
            return None
